CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roles(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE permissions(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE role_permissions(role_id INTEGER NOT NULL REFERENCES roles(id), permission_id INTEGER NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE branches(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, city TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE customers(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, phone TEXT NOT NULL, address TEXT NOT NULL, branch_id INTEGER NOT NULL REFERENCES branches(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_kyc(customer_id INTEGER PRIMARY KEY REFERENCES customers(id), status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Verified','Rejected')), document_reference TEXT NOT NULL DEFAULT '', reviewed_by INTEGER REFERENCES users(id), reviewed_at TEXT);
CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password_hash BLOB NOT NULL, salt BLOB NOT NULL, iterations INTEGER NOT NULL CHECK(iterations>=100000), customer_id INTEGER REFERENCES customers(id), failed_attempts INTEGER NOT NULL DEFAULT 0 CHECK(failed_attempts>=0), locked_until INTEGER NOT NULL DEFAULT 0, must_change INTEGER NOT NULL DEFAULT 1 CHECK(must_change IN(0,1)), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE user_roles(user_id INTEGER NOT NULL REFERENCES users(id), role_id INTEGER NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE account_types(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE bank_accounts(id INTEGER PRIMARY KEY, number TEXT UNIQUE NOT NULL, customer_id INTEGER NOT NULL REFERENCES customers(id), type_id INTEGER NOT NULL REFERENCES account_types(id), balance INTEGER NOT NULL DEFAULT 0 CHECK(typeof(balance)='integer' AND balance>=0), status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN('Active','Frozen','Closed')), nickname TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE transactions(id INTEGER PRIMARY KEY, reference TEXT UNIQUE NOT NULL, account_id INTEGER NOT NULL REFERENCES bank_accounts(id), kind TEXT NOT NULL CHECK(kind IN('Deposit','Withdrawal','Transfer In','Transfer Out','Loan Disbursement','Loan Repayment')), amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0), note TEXT NOT NULL, actor_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE transfers(id INTEGER PRIMARY KEY, idempotency_key TEXT UNIQUE NOT NULL, from_account INTEGER NOT NULL REFERENCES bank_accounts(id), to_account INTEGER NOT NULL REFERENCES bank_accounts(id), amount INTEGER NOT NULL CHECK(amount>0), debit_transaction INTEGER NOT NULL REFERENCES transactions(id), credit_transaction INTEGER NOT NULL REFERENCES transactions(id), CHECK(from_account<>to_account));
CREATE TABLE loans(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), account_id INTEGER NOT NULL REFERENCES bank_accounts(id), principal INTEGER NOT NULL CHECK(principal>0), annual_rate_bps INTEGER NOT NULL CHECK(annual_rate_bps BETWEEN 0 AND 10000), term_months INTEGER NOT NULL CHECK(term_months BETWEEN 1 AND 360), purpose TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Approved','Rejected','Repaid')), paid INTEGER NOT NULL DEFAULT 0 CHECK(paid>=0), total_due INTEGER NOT NULL CHECK(total_due>=principal), reviewed_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, approved_at TEXT);
CREATE TABLE loan_repayments(id INTEGER PRIMARY KEY, loan_id INTEGER NOT NULL REFERENCES loans(id), transaction_id INTEGER UNIQUE NOT NULL REFERENCES transactions(id), amount INTEGER NOT NULL CHECK(amount>0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE debit_cards(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES bank_accounts(id), masked_number TEXT UNIQUE NOT NULL, status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN('Active','Blocked')), issued_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employees(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL UNIQUE REFERENCES users(id), branch_id INTEGER NOT NULL REFERENCES branches(id), title TEXT NOT NULL);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts(id INTEGER PRIMARY KEY, username TEXT NOT NULL, successful INTEGER NOT NULL CHECK(successful IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), message TEXT NOT NULL, resolved INTEGER NOT NULL DEFAULT 0 CHECK(resolved IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE application_settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX idx_accounts_customer ON bank_accounts(customer_id);
CREATE INDEX idx_transactions_date ON transactions(created_at);
CREATE INDEX idx_transactions_account ON transactions(account_id,id);
CREATE INDEX idx_loans_customer ON loans(customer_id,status);
CREATE INDEX idx_audit_date ON audit_logs(created_at);
INSERT INTO schema_migrations(version) VALUES(1);
